1	// Keyboard/mouse input that survives lost key-up events, plus F3 debug panel.
2	// Ported from guizang-game-skill scripts/input.js (AGPL-3.0), tailored for a
3	// click-driven tower defense: pointer position, clicks, keys, touch buttons.
4	export const keys = new Set(), pressed = new Set(), mouse = { x: 0, y: 0 };
5	const OPP = { KeyW: 'KeyS', KeyS: 'KeyW', KeyA: 'KeyD', KeyD: 'KeyA' }; let log = [];
6	const note = (s) => { log.push(s); log = log.slice(-8); };
7	export let touchMode = false;
8	
9	addEventListener('keydown', (e) => {
10	  if (e.isComposing || e.keyCode === 229) return;                                   // IME composing: not ours
11	  if (/^(Meta|Alt|Control)/.test(e.code)) { keys.clear(); return; }                 // shortcuts swallow key-ups: start clean
12	  if (e.metaKey || e.altKey || e.ctrlKey) return;
13	  if (!e.repeat) { note('↓' + e.code); if (OPP[e.code]) keys.delete(OPP[e.code]); }
14	  if (!keys.has(e.code)) pressed.add(e.code); keys.add(e.code);
15	  if (e.code === 'Space' || e.code === 'Tab') e.preventDefault();
16	});
17	addEventListener('keyup', (e) => { note('↑' + e.code); keys.delete(e.code); if (/^(Meta|Alt|Control)/.test(e.code)) keys.clear(); });
18	for (const ev of ['blur', 'focus', 'pagehide']) addEventListener(ev, () => { note('[' + ev + ']'); keys.clear(); });
19	document.addEventListener('visibilitychange', () => keys.clear());
20	addEventListener('mousemove', (e) => { mouse.x = e.clientX / innerWidth * 2 - 1; mouse.y = -(e.clientY / innerHeight) * 2 + 1; });
21	// A touch must not permanently disable mouse input (touchscreen laptops, stray
22	// palm contact): only suppress the synthetic mousedown that trails a real touch.
23	// AND: a press on any DOM UI element (cards, tower panel, HUD buttons) must NOT
24	// queue a scene click — otherwise the next frame raycasts through the UI,
25	// deselecting the selection before the element's own click handler runs.
26	let lastTouchT = -1e9;
27	const isScene = (e) => !e.target || e.target.id === 'gl' || e.target === document.body || e.target === document.documentElement;
28	addEventListener('mousedown', (e) => {
29	  if (e.button !== 0 || !isScene(e)) return;
30	  if (touchMode && performance.now() - lastTouchT < 1200) return;   // synthetic echo of a real touch
31	  note('click'); pressed.add('Click');
32	});
33	addEventListener('contextmenu', (e) => e.preventDefault());
34	export function endFrame() { pressed.clear(); }
35	
36	// F3 panel; extra() supplies game state lines.
37	export function debugPanel(extra = () => '') {
38	  const d = document.createElement('div');
39	  d.style.cssText = 'position:fixed;left:8px;top:60px;z-index:99;font:11px ui-monospace,Menlo,monospace;color:#9fe0c0;background:rgba(0,0,0,.55);padding:6px 8px;white-space:pre;display:none;pointer-events:none';
