591	// ==================== FX ====================
592	function spawnBurst(x, y, color, n = 8, speed = 80, life = .5, size = 2) {
593	  for (let i = 0; i < n; i++) {
594	    const a = Math.random() * Math.PI * 2, sp = speed * (.35 + Math.random());
595	    particles.push({
596	      x, y, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - speed * .3,
597	      life: life * (.6 + Math.random() * .7), max: life, size: size * (.5 + Math.random()),
598	      color, grav: 300, drag: .99,
599	    });
600	  }
601	}
602	function updateFX(dt) {
603	  for (let i = particles.length - 1; i >= 0; i--) {
604	    const p = particles[i];
605	    p.life -= dt;
606	    if (p.life <= 0) { particles.splice(i, 1); continue; }
607	    p.vy += (p.grav || 0) * dt;
608	    p.vx *= (p.drag || 1); p.vy *= (p.drag || 1);
609	    p.x += p.vx * dt; p.y += p.vy * dt;
610	  }
611	  for (let i = floats.length - 1; i >= 0; i--) {
612	    const f = floats[i];
613	    f.life -= dt; f.y -= 30 * dt;
614	    if (f.life <= 0) floats.splice(i, 1);
615	  }
616	  if (shakeT > 0) shakeT = Math.max(0, shakeT - dt);
617	  if (flashT > 0) flashT = Math.max(0, flashT - dt);
618	  audio.update(dt);
619	}
