621	// ==================== update ====================
622	function update(dt) {
623	  if (mode === 'test') {
624	    if (paused) return;
625	    if (hitstop > 0) { hitstop -= dt; return; }
626	    const before = physics.state().elapsed;
627	    physics.step(dt, true);
628	    const st = physics.state();
629	    if (st.elapsed <= before && st.elapsed === 0) return;
630	    testPeak = Math.max(testPeak, st.peakStress);
631	    const ev = physics.drainEvents();
632	    for (const e of ev) {
633	      if (e.type === 'snap') {
634	        spawnBurst(e.member.a.x, e.member.a.y, '#e86a5b', 18, 160, .7, 2.6);
635	        spawnBurst(e.member.b.x, e.member.b.y, '#f0c98a', 12, 120, .6, 2);
636	        shakeT = .35; shakeAmp = 7; hitstop = .07;
637	        audio.sfx.snap();
638	      }
639	    }
640	    const maxStress = Math.max(0, ...physics.stressList());
641	    if (maxStress > .62) {
642	      stressSoundT -= dt;
643	      if (stressSoundT <= 0) { stressSoundT = .55; audio.sfx.stress(); }
644	      if (maxStress > .8) { shakeT = Math.max(shakeT, .08); shakeAmp = Math.max(shakeAmp, 1.4); }
645	    }
646	    if (st.failure) { failLevel(st.failure); return; }
647	    if (st.car && st.car.reached) { finishLevel(false); return; }
648	    updateHUD();
649	  }
650	}
