779	function stressColor(s, a = 1) {
780	  s = clamp(s, 0, 1);
781	  let r, g, b;
782	  if (s < .55) {
783	    const t = s / .55;
784	    r = 115 + (232 - 115) * t; g = 224 + (204 - 224) * t; b = 182 + (110 - 182) * t;
785	  } else {
786	    const t = (s - .55) / .45;
787	    r = 232 + (232 - 232) * t; g = 204 + (106 - 204) * t; b = 110 + (91 - 110) * t;
788	  }
789	  return `rgba(${r | 0},${g | 0},${b | 0},${a})`;
790	}
