}
function randomizeDecoys(lvl, rng) {
  for (const c of lvl.cells) {
    if (c.onPath || c.t === 'cross') continue;
    const t = shuffle(rng, ['straight', 'elbow', 'tee', 'straight', 'elbow', 'cross'])[0];
    c.t = t;
