// A self-avoiding path from column 0 to the last column. Weighted random DFS
// biased east and vertically, with a little westward wandering for switchbacks.
function genPath(rng, spec, blocked, minLen, maxLen) {
  const cols = spec.cols, rows = spec.rows;
  for (let attempt = 0; attempt < 90; attempt++) {
    const startRow = (rng() * rows) | 0;
    const start = { r: startRow, c: 0 };
    if (blocked.has(key(start.r, start.c))) continue;
    const visited = new Set([key(start.r, start.c)]);
    let best = null;
    const dfs = (r, c, path) => {
      if (best) return true;
      if (path.length > maxLen) return false;
      if (c === cols - 1 && path.length >= minLen && turnsOf(path) >= 2) {
        best = path.slice();
        return true;
      }
      const cand = [];
      for (const d of [1, 0, 2, 3]) {
        const nr = r + DR[d], nc = c + DC[d];
        if (!inB(spec, nr, nc)) continue;
        if (blocked.has(key(nr, nc))) continue;
        if (visited.has(key(nr, nc))) continue;
        const w = d === 1 ? 3.2 : d === 3 ? 0.55 : 1.5;
        cand.push({ d, nr, nc, p: rng() / w });
      }
      cand.sort((a, b) => a.p - b.p);
      for (const o of cand) {
        visited.add(key(o.nr, o.nc));
        path.push({ r: o.nr, c: o.nc });
        if (dfs(o.nr, o.nc, path)) return true;
        path.pop();
        visited.delete(key(o.nr, o.nc));
      }
      return false;
    };
    dfs(start.r, start.c, [start]);
    if (best) return best;
  }
  return null;
}

