// ==================== update ====================
function update(dt) {
  if (mode === 'play' && !paused) {
    if (hitstop > 0) hitstop = Math.max(0, hitstop - dt);
    else {
      elapsed += dt;
      flowPhase += dt;
      updateFX(dt);
    }
    hudT += dt;
    if (hudT >= .2) { hudT = 0; updateHUD(); }
    if (endTimer > 0) {
      endTimer -= dt;
      if (endTimer <= 0 && pendingEnd && !noAuto) showEnd();
    }
    audio.update(dt);
  } else if (mode === 'win' || mode === 'over') {
    if (hitstop > 0) hitstop = Math.max(0, hitstop - dt);
    else { flowPhase += dt * .7; updateFX(dt); }
    if (endTimer > 0) {
      endTimer -= dt;
      if (endTimer <= 0 && pendingEnd && !noAuto) showEnd();
    }
    audio.update(dt);
  } else {
    flowPhase += dt * .55;
    updateFX(dt);
    audio.update(dt);
