  ctx.save();
  ctx.globalCompositeOperation = 'screen';
  for (let i = 0; i < 22; i++) {
    const x = (i * 137.3 + Math.sin(t * .17 + i) * 22 + W) % W;
    const y = 70 + ((i * 73.7 + t * (2 + i % 4)) % (H - 130));
    const a = .04 + .10 * (.5 + .5 * Math.sin(t * 1.3 + i * 2.1));
