  ctx.lineTo(x + s * .87, y + s * .07);
  ctx.strokeStyle = 'rgba(200,220,255,.055)'; ctx.lineWidth = 1; ctx.stroke();
  // inner inset
  rr(ctx, x + s * .1, y + s * .1, s * .8, s * .8, s * .06);
  ctx.strokeStyle = 'rgba(215,160,90,.055)'; ctx.lineWidth = .8; ctx.stroke();
