  if (!hasPipe) {
    ctx.strokeStyle = `rgba(120,224,200,${.035 + h * .035})`;
    ctx.lineWidth = .8;
    ctx.beginPath();
    if (h < .33) { ctx.arc(x + s / 2, y + s / 2, s * (.15 + h * .05), .2, 2.7); }
    else if (h < .66) {
      ctx.moveTo(x + s * .3, y + s * .68); ctx.quadraticCurveTo(x + s * .5, y + s * .36, x + s * .7, y + s * .68);
    } else {
