  const remain = Math.max(0, levelDef.budget - usedMoves);
  const timeBonus = Math.max(0, Math.round(levelDef.par - time));
  return Math.max(0, Math.round(remain * 12 + stars * 60 + timeBonus * 2));
}

function winLevel(forced = false) {
