// T8 valve: open vs closed changes reachability
G.setLevel(8);
G.setSolutionState();
const open8 = G.flowSnapshot();
const valve8 = level.cells.find(c => c.onPath && c.t === 'valve');
G.setRot(valve8.r, valve8.c, (valve8.sol + 1) & 3);
const shut8 = G.flowSnapshot();
ok('T8', open8.solved && !shut8.solved && shut8.reached < open8.reached, `开=${open8.solved} 闭=${shut8.solved} reached ${open8.reached}→${shut8.reached}`);

