import { createRequire } from 'module';
const require = createRequire('/tmp/pw/node_modules/');
const { chromium } = require('playwright');
const BASE = 'http://localhost:8623/aqua-conduit/';
const OUT = '/mnt/tos/workspace/.scratch/guizang3/aqua-conduit/';
const browser = await chromium.launch({ executablePath: '/usr/local/bin/chromium', args: ['--no-sandbox', '--use-gl=swiftshader'] });

async function shot(name, url, viewport, fn) {
  const page = await browser.newPage({ viewport });
  const errors = [];
  page.on('console', m => { if (['error', 'warning'].includes(m.type())) errors.push(m.type() + ':' + m.text()); });
  page.on('pageerror', e => errors.push('pageerror:' + String(e)));
  await page.goto(BASE + url, { waitUntil: 'load' });
  await page.waitForTimeout(900);
  if (fn) { await page.evaluate(fn); await page.waitForTimeout(1100); }
  await page.screenshot({ path: OUT + name, type: name.endsWith('.jpg') ? 'jpeg' : 'png', quality: name.endsWith('.jpg') ? 92 : undefined });
  console.log(name, 'errors=', JSON.stringify(errors));
  await page.close();
}

