await mobile.waitForTimeout(200);
const touchState = await mobile.evaluate(([r, c]) => ({ used: window.G.state().used, rot: window.G.cellInfo(r, c).rot, sol: window.G.cellInfo(r, c).sol }), [tPos.r, tPos.c]);
