  errors: directErrors,
  external: directRequests.filter(u => !u.startsWith('http://localhost:8623') && !u.startsWith('data:') && !u.startsWith('blob:')),
};

console.log(JSON.stringify({ rounds, input, directInfo }, null, 2));
await browser.close();

